<script setup>
import {ref,computed} from 'vue';
import {api} from '../lib/workspace';
const props=defineProps({target:{type:Object,required:true},kind:{type:String,default:'cnpj'}});
const busy=ref(false),error=ref(''),result=ref(null),selected=ref([]),provider=ref('auto');
const labels={name:'Razão social',trade_name:'Nome fantasia',tax_id:'CNPJ',address:'Logradouro',number:'Número',district:'Bairro',postal_code:'CEP',city:'Município',ibge:'Código IBGE',state:'UF',email:'E-mail',phone:'Telefone',cnae:'CNAE principal','profile.legal_nature':'Natureza jurídica','profile.registration_status':'Situação cadastral','profile.complement':'Complemento','profile.ie_status':'Situação da IE','profile.state_registrations':'Inscrições estaduais','profile.secondary_cnaes':'CNAEs secundários'};
const fields=computed(()=>Object.entries(result.value?.fields||{}).flatMap(([key,value])=>key==='profile'?Object.entries(value).filter(([k])=>!k.startsWith('lookup_')).map(([k,v])=>({key:`profile.${k}`,value:v})): [{key,value}]).filter(r=>r.value!==''&&r.value!==null));
function current(key){return key.startsWith('profile.')?props.target.profile?.[key.slice(8)]:props.target[key];}
function display(value){if(Array.isArray(value))return value.map(v=>typeof v==='object'?`${v.state}: ${v.number} (${v.active===true?'ativa':v.active===false?'inativa':'situação não informada'})`:v).join('; ')||'Nenhum registro retornado';return ({unknown:'Não informado',not_found:'Não localizado nesta fonte',registered:'Inscrições encontradas',exempt:'Isento',not_applicable:'Não aplicável'})[value]||value||'—';}
async function query(){busy.value=true;error.value='';result.value=null;try{const value=props.kind==='cnpj'?props.target.tax_id:props.target.postal_code;result.value=await api(`/lookups/${props.kind}/${encodeURIComponent(value||'')}?provider=${provider.value}`);selected.value=fields.value.filter(r=>!current(r.key)||Array.isArray(current(r.key))&&!current(r.key).length).map(r=>r.key);}catch(e){error.value=e.message;}finally{busy.value=false;}}
function apply(){for(const r of fields.value.filter(r=>selected.value.includes(r.key))){if(r.key.startsWith('profile.')){props.target.profile??={};props.target.profile[r.key.slice(8)]=JSON.parse(JSON.stringify(r.value));}else props.target[r.key]=r.value;}props.target.profile??={};props.target.profile.lookup_source=result.value.provider;props.target.profile.lookup_date=result.value.fetched_at;result.value=null;}
</script>
<template><div class="lookup-assist"><div class="actions"><select v-model="provider" :aria-label="`Fonte de consulta de ${kind.toUpperCase()}`"><option value="auto">Fonte automática</option><template v-if="kind==='cnpj'"><option value="cnpjws">CNPJ.ws</option><option value="receitaws">ReceitaWS</option><option value="brasilapi">BrasilAPI</option></template><template v-else><option value="viacep">ViaCEP</option><option value="brasilapi_cep">BrasilAPI</option></template></select><button type="button" class="button outline small" @click="query" :disabled="busy">{{busy?'Consultando…':`Consultar ${kind.toUpperCase()}`}}</button></div><p v-if="error" class="message error" role="alert">{{error}} Você pode continuar preenchendo manualmente.</p><section v-if="result" class="lookup-review"><p class="message" :class="result.stale||result.status!=='ok'?'warning':'subtle'">{{result.message}}</p><small v-if="result.provider">Fonte: {{result.provider}} · {{result.fetched_at}} · {{result.cached?'Cache':'Consulta online'}}</small><div v-if="fields.length" class="table-scroll"><table><thead><tr><th>Aplicar</th><th>Campo</th><th>Atual</th><th>Consultado</th></tr></thead><tbody><tr v-for="r in fields" :key="r.key"><td><input type="checkbox" v-model="selected" :value="r.key" :aria-label="`Aplicar ${labels[r.key]||r.key}`"/></td><td>{{labels[r.key]||r.key}}</td><td>{{display(current(r.key))}}</td><td>{{display(r.value)}}</td></tr></tbody></table></div><div class="actions"><button type="button" class="button" @click="result=null">Fechar consulta</button><button v-if="fields.length" type="button" class="button primary" :disabled="!selected.length" @click="apply">Aplicar campos selecionados</button></div></section></div></template>
